//! Postrider's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! Only Postrider's own records sync: the accounts it reads and the calendar
//! server. Mail, folders and events stay on their servers; IMAP and CalDAV
//! are their sync, and the server reads them live ([`Inbox`], [`Day`]).
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod mail;
mod model;
mod protocol;
mod user;

pub use account::{Me, Role, UserInfo, WorkspaceInfo, clean_name, normalize_email, url_key_from};
pub use mail::{
    AccountState, AccountStatus, Answer, Asked, Attachment, Calendar, CalendarConnect,
    CalendarCreate, CalendarPatch, Conversation, Day, Event, Folder, FolderLink, FolderRole, HUES,
    Inbox, KeptInInbox, Listing, MailAccount, MailAccountConnect, MailAccountCreate,
    MailAccountPatch, MailRef, MailSummary, MarkedRead, Message, MoveMail, NewMail, Newsletter,
    NewsletterRef, Newsletters, RenameFolder, Reply, Rewrite, Rewritten, SenderProblem, Senders,
    ServerCalendar, SettingAside, UnsubscribeSent, Unsubscribed, Unsubscribing,
};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use user::User;
